s = input().split()
n = int(s[0])
a = [[i, 0] for i in range(1, n + 1)]
q = int(s[1])
direction_map = {"L": (-1, 0), "U": (0, 1), "R": (1, 0), "D": (0, -1)}

for _ in range(q):
    s = input().split()
    if s[0] == '1':
        dx, dy = direction_map[s[1]]
        new_head = [a[0][0] + dx, a[0][1] + dy]
        a = [new_head] + a[:-1]
    else:
        print(a[int(s[1]) - 1][0], a[int(s[1]) - 1][1])

